def max_product(num_str, N, K):
    n = len(num_str)
    dp = [[0] * (K+1) for _ in range(n+1)]

    for i in range(n):
        for j in range(K+1):
            if j == 0:
                dp[i+1][j] = int(num_str[i])
            elif j == 1:
                dp[i+1][j] = int(num_str[i]) * int(num_str[i-1])
            else:
                dp[i+1][j] = max(dp[i][j-1], dp[i-1][j-1] * int(num_str[i]))

    return dp[n][K]
