def verify_isbn(isbn):
    isbn_digits = isbn.replace("-", "")
    checksum = isbn_digits[-1]
    if checksum in ["X", "x"]:
        checksum = 10
    total = 0
    for i, digit in enumerate(isbn_digits[:-1]):
        total += (i + 1) * int(digit)
    if total % 11 == checksum:
        return "Right"
    else:
        correction = (11 - (total % 11)) % 11
        correction = "X" if correction == 10 else str(correction)
        return isbn[:-1] + correction
