def max_herb_value(T, M, herbs):
    # Initialize a dictionary to store the maximum value for each time available
    max_values = {}

    # Loop through the herbs and calculate the maximum value for each time available
    for herb in herbs:
        time_required, value = herb
        for time in range(T + 1):
            if time_required > time:
                # If the time required is greater than the available time, set the maximum value to 0
                max_values[time] = 0
            else:
                # If the time required is less than or equal to the available time, calculate the maximum value
                max_values[time] = max(max_values.get(time - time_required, 0) + value, max_values.get(time, 0))

    # Return the maximum value for the total time available
    return max_values[T]
