def min_remaining_space(V, n, volumes):
    # Initialize a 2D table to store the results of sub-problems
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Base case: no items or no space left in the box
    for i in range(V + 1):
        dp[i][0] = 0
    for j in range(n + 1):
        dp[0][j] = 0

    # Fill in the table
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1] + volumes[j - 1])

    # Return the minimum remaining space
    return V - dp[V][n]
```

