def calculate_arrangements(n, m, a):
    # Initialize a 2D array to store the results
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: only one pot
    for i in range(n + 1):
        dp[i][1] = 1

    # Populate the table
    for i in range(2, m + 1):
        for j in range(n + 1):
            # Case 1: use the current type
            if j > 0:
                dp[j][i] += dp[j - 1][i - 1]
            # Case 2: use the previous type
            if j > 1 and a[j - 1] > 0:
                dp[j][i] += dp[j - 2][i - 1]

    # Return the result
    return dp[n][m]
```

